14	final class Households {
15	
16	    private Households() {
17	    }
18	
19	    /**
20	     * Canonicalizes a last name for case-insensitive, whitespace-insensitive comparison:
21	     * trims the ends, collapses every run of whitespace to a single space and lower-cases
22	     * the result. Returns an empty string when {@code lastName} is {@code null}.
23	     */
24	    private static String normalizeName(String lastName) {
25	        if (lastName == null) {
26	            return "";
27	        }
28	        return lastName.trim().replaceAll("\\s+", " ").toLowerCase();
29	    }
30	
31	    /**
32	     * Canonicalizes an address using the same normalization applied when an owner is created
33	     * (see {@link Addresses#normalize(String)}), so household comparisons see the stored,
34	     * abbreviation-expanded form. Returns an empty string when {@code address} is
35	     * {@code null}.
36	     */
37	    private static String normalizeAddress(String address) {
38	        String normalized = Addresses.normalize(address);
39	        return normalized == null ? "" : normalized;
40	    }
41	
42	    /**
43	     * Whether {@code owner} belongs to the household identified by {@code lastName} and
44	     * {@code address}, comparing the last name and the address in their canonical forms.
45	     */
46	    static boolean matches(Owner owner, String lastName, String address) {
47	        return normalizeName(lastName).equals(normalizeName(owner.getLastName()))
48	                && normalizeAddress(address).equals(normalizeAddress(owner.getAddress()));
49	    }
50	
51	    /**
52	     * The stable identifier shared by every owner in the household identified by
53	     * {@code lastName} and {@code address}. Derived purely from the canonical household key,
54	     * so the same household always yields the same id without any coordination.
55	     */
56	    static String id(String lastName, String address) {
57	        String key = normalizeName(lastName) + "\n" + normalizeAddress(address);
58	        return "H-" + Hashes.upperHexPrefix(key, 12);
59	    }
60	
61	    /**
62	     * The household id a create request resolves to: the shared id of the household it joins
63	     * when it opts in ({@code sharesHousehold} true) and an existing owner already lives at
64	     * the same address under the same last name, otherwise an empty string. Mirrors the
65	     * assignment performed by {@link AssignHousehold}.
66	     */
67	    static String resolveHouseholdId(OwnerFieldsDto request, OwnerRepository ownerRepository) {
68	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
69	            return "";
70	        }
71	        for (Owner existing : ownerRepository.findAll()) {
72	            if (matches(existing, request.getLastName(), request.getAddress())) {
73	                return id(request.getLastName(), request.getAddress());
74	            }
75	        }
76	        return "";
77	    }
78	}
